export const title = "How to Share One Small Desk Between Two People at Different Times";
export const metaTitle = "How to Share One Small Desk Between Two People";
export const metaDescription = "Design a clear handover. Practical measurements, original diagrams and fit checks for shared workspaces in small workspaces.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-10-27";
